Diagnosis: Atomic routes need replay protection to prevent double-execution.

Files to change:
- pallets/x3-router/src/lib.rs
- pallets/x3-router/src/replay.rs (new)

Patch:
```rust
// pallets/x3-router/src/replay.rs
use frame_support::{storage::bounded_btree_map, BoundedVec};
use sp_runtime::RuntimeDebug;

#[derive(RuntimeDebug, PartialEq, Eq, scale::Encode, scale::Decode, Clone)]
pub struct ReplayGuard<AccountId, BlockNumber> {
    pub nonce: u64,
    pub route_id: [u8; 32],
    pub expires_at: BlockNumber,
}

// Storage: seen nonces per route
#[frame_support::storage_alias]
pub type SeenNonces<T: Config> = StorageMap<
    _,
    Identity,
    [u8; 32], // route_id
    u64,       // highest nonce seen
>;

pub fn check_and_record_replay<T: Config>(
    route_id: [u8; 32],
    nonce: u64,
    expires_at: T::BlockNumber,
) -> Result<(), DispatchError> {
    let seen = SeenNonces::<T>::get(route_id).unwrap_or(0);
    ensure!(nonce > seen, Error::<T>::ReplayDetected);
    ensure!(frame_system::Pallet::<T>::block_number() <= expires_at, Error::<T>::RouteExpired);
    SeenNonces::<T>::insert(route_id, nonce);
    Ok(())
}
```

