Diagnosis: The UAK needs a runtime invariant that verifies canonical_supply == native + evm + svm + external_locked + pending after every block.

Files to change:
- pallets/uak/src/lib.rs
- pallets/uak/src/invariant.rs (new)

Patch:
```rust
// pallets/uak/src/invariant.rs
use frame_support::traits::{Get, EnsureOrigin};
use sp_arithmetic::traits::Zero;

/// Supply invariant: canonical_supply == native + evm + svm + external_locked + pending
pub fn verify_supply_invariant<T: Config>() -> Result<(), &'static str> {
    let canonical = CanonicalSupply::<T>::get();
    let native = NativeBalance::<T>::get();
    let evm = EVMBalance::<T>::get();
    let svm = SVMBalance::<T>::get();
    let external_locked = ExternalLocked::<T>::get();
    let pending = PendingTransfers::<T>::get();

    let computed = native
        .checked_add(&evm)
        .ok_or("evm overflow")?
        .checked_add(&svm)
        .ok_or("svm overflow")?
        .checked_add(&external_locked)
        .ok_or("external_locked overflow")?
        .checked_add(&pending)
        .ok_or("pending overflow")?;

    if canonical != computed {
        log::error!(
            target: "uak",
            "SUPPLY INVARIANT VIOLATION: canonical={} computed={}",
            canonical, computed
        );
        return Err("canonical supply invariant violated");
    }
    Ok(())
}
```

