Contract diagnosis: X3Vault lacks reentrancy guard, slippage checks, and deadline enforcement.

Security assumptions:
- External calls to token contracts are untrusted
- Cross-VM bridge calls may callback into this contract
- No assumption about tx.origin

Patch:
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

contract X3Vault is ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    error InsufficientOutput(uint256 expected, uint256 actual);
    error DeadlineExpired(uint256 deadline, uint256 blockTimestamp);
    error InvalidRoute();
    error ReplayDetected(bytes32 routeId, uint64 nonce);

    struct DepositParams {
        address token;
        uint256 amount;
        uint256 minOutput;
        uint256 deadline;
        bytes32 routeId;
        uint64 nonce;
    }

    mapping(bytes32 => uint64) public seenNonces;

    function deposit(DepositParams calldata params)
        external
        nonReentrant
        whenNotPaused
        returns (uint256 outputAmount)
    {
        // Deadline check
        if (block.timestamp > params.deadline) {
            revert DeadlineExpired(params.deadline, block.timestamp);
        }

        // Replay protection
        if (seenNonces[params.routeId] >= params.nonce) {
            revert ReplayDetected(params.routeId, params.nonce);
        }
        seenNonces[params.routeId] = params.nonce;

        // Transfer tokens in
        IERC20(params.token).safeTransferFrom(msg.sender, address(this), params.amount);

        // ... routing logic ...

        // Slippage check
        if (outputAmount < params.minOutput) {
            revert InsufficientOutput(params.minOutput, outputAmount);
        }

        emit Deposited(params.routeId, params.nonce, params.token, params.amount, outputAmount);
    }

    event Deposited(bytes32 indexed routeId, uint64 nonce, address token, uint256 amount, uint256 outputAmount);
}
```

Events/errors added:
